// This is the dump first version, created just ot setup all the pipelines for
// the containers generation.

syntax = "proto3";

package stations_service.v1;
option go_package = "/stations_service/v1";
import "validate/validate.proto";
import "google/api/annotations.proto";
import "google/protobuf/field_mask.proto";
import "google/protobuf/timestamp.proto";
import "google/type/date.proto";
import "qcpp/v1/qcpp.proto";

enum EVSEStatusEnum {
  EVSE_STATUS_ENUM_UNSPECIFIED = 0;
  // Available
  EVSE_STATUS_ENUM_AVAILABLE = 1;
  // Someone is at the parking lot
  EVSE_STATUS_ENUM_OCCUPIED = 2;
  // Someone illegally blocks the evse
  EVSE_STATUS_ENUM_ILLEGALLY_BLOCKED = 3;
  // The EVSE is offline
  EVSE_STATUS_ENUM_OFFLINE = 4;
  // The EVSE is charging
  EVSE_STATUS_ENUM_CHARGING = 5;
  // The evse is temporary or forever not working
  EVSE_STATUS_ENUM_OUT_OF_SERVICE = 6;
  // the evse is retired
  EVSE_STATUS_ENUM_REMOVED = 7;
  // the evse is reserved, will be overwritten by illegally blocked, can not be
  // overwritten by occupied
  EVSE_STATUS_ENUM_RESERVED = 8;
  // not yet available
  EVSE_STATUS_ENUM_INOPERATIVE = 9;
}

enum LocationTypeEnum {
  LOCATION_TYPE_ENUM_UNSPECIFIED = 0;
  LOCATION_TYPE_ENUM_ON_STREET = 1;
  LOCATION_TYPE_ENUM_PARKING_GARAGE = 2;
  LOCATION_TYPE_ENUM_UNDERGROUND_GARAGE = 3;
  LOCATION_TYPE_ENUM_PARKING_LOT = 4;
  LOCATION_TYPE_ENUM_OTHER = 5;
  LOCATION_TYPE_ENUM_UNKNOWN = 6;
}

// Is network Qwello or from one of the roaming providers
enum NetworkRoamingSourceEnum {
  // notset
  NETWORK_ROAMING_SOURCE_ENUM_UNSPECIFIED = 0;
  // One of Qwello networks
  NETWORK_ROAMING_SOURCE_ENUM_QWELLO = 1;
  // E-clearing
  NETWORK_ROAMING_SOURCE_ENUM_E_CLEARING = 2;
  // Hubject
  NETWORK_ROAMING_SOURCE_ENUM_HUBJECT = 3;
}
// Just answers the question if it is Qwello or Roaming Location
enum LocationSourceEnum {
  LOCATION_SOURCE_ENUM_UNSPECIFIED = 0;
  LOCATION_SOURCE_ENUM_QWELLO = 1;
  LOCATION_SOURCE_ENUM_ROAMING = 2;
}
// One of the states of the station. We can change more fields if it is in the
// draft state
enum ReadinessEnum {
  READINESS_ENUM_UNSPECIFIED = 0;
  READINESS_ENUM_DRAFT = 1;
  // once the Location is ready you can not change the evse_id and it is
  // propagated to the other services
  READINESS_ENUM_READY = 2;
  // Once the location is provisioned by the tech service and is ready to go
  // live
  READINESS_ENUM_COMMISSIONED = 3;
}
// If we simulate station with the simulator or it is a real station
enum SimulatedEnum {
  // not set
  SIMULATED_ENUM_UNSPECIFIED = 0;
  // emulator.staging.qwello.eu is used for the communication simulation
  SIMULATED_ENUM_SIMULATED = 1;
  // Eugene is used for the communication
  SIMULATED_ENUM_REAL = 2;
}
// If we export the station to public
enum AccessibilityEnum {
  ACCESSIBILITY_ENUM_UNSPECIFIED = 0;
  // use only internally
  ACCESSIBILITY_ENUM_INTERNAL = 1;
  // use for roaming, once the station is in this state, it can not become
  // internal anymore
  ACCESSIBILITY_ENUM_PUBLIC = 2;
}
enum RegistrationEnum {
  // the value of register_at does not matter
  REGISTRATION_ENUM_UNSPECIFIED = 0;
  // the location group is registered (register_at is not null)
  REGISTRATION_ENUM_REGISTERED = 1;
  // the location group is not registered (register_at is null)
  REGISTRATION_ENUM_NOT_REGISTERED = 2;
}
// The type of the connector
enum ConnectorTypeEnum {
  CONNECTOR_TYPE_ENUM_UNSPECIFIED = 0;
  CONNECTOR_TYPE_ENUM_SCHUKO = 1;
  CONNECTOR_TYPE_ENUM_TYPE2 = 2;
  CONNECTOR_TYPE_ENUM_CCS = 3;
  CONNECTOR_TYPE_ENUM_CHADEMO = 4;
}

enum ConnectorFormatEnum {
  CONNECTOR_FORMAT_ENUM_UNSPECIFIED = 0;
  CONNECTOR_FORMAT_ENUM_SOCKET = 1;
  CONNECTOR_FORMAT_ENUM_CABLE = 2;
}
// The format of the connector, if it has integrated cable or not.
enum PowerTypeEnum {
  POWER_TYPE_ENUM_UNSPECIFIED = 0;
  POWER_TYPE_ENUM_AC = 1;
  POWER_TYPE_ENUM_DC = 2;
}
// If EVSE is paired to the Pole
enum EVSEPairedEnum {
  EVSE_PAIRED_ENUM_UNSPECIFIED = 0;
  EVSE_PAIRED_ENUM_NOT_PAIRED = 1;
  EVSE_PAIRED_ENUM_PAIRED = 2;
}

enum FeatureEnum {
  FEATURE_ENUM_UNSPECIFIED = 0;
  // can reserve from app
  FEATURE_ENUM_RESERVATION = 1;
  // can authorize from app
  FEATURE_ENUM_REMOTE = 2;
  // has rfid reader
  FEATURE_ENUM_RFID_READER = 3;
  // can pay with credit/debit cards
  FEATURE_ENUM_CREDIT_CARD_PAYABLE = 4;
}

enum SyncToBackend {
  SYNC_TO_BACKEND_UNSPECIFIED = 0;
  SYNC_TO_BACKEND_YES = 1;
  SYNC_TO_BACKEND_NO = 2;
}

// If a Pole is supposed to be in the Maintenance Mode or not
enum MaintenanceModeEnum {
  MAINTENANCE_MODE_UNSPECIFIED = 0;
  MAINTENANCE_MODE_ON = 1;
  MAINTENANCE_MODE_OFF = 2;
}

enum EVSEReservationStatus {
  EVSE_RESERVATION_STATUS_UNSPECIFIED = 0;
  EVSE_RESERVATION_STATUS_NOT_RESERVED = 1;
  EVSE_RESERVATION_STATUS_RESERVED = 2;
}

enum ProviderTypeEnum {
  PROVIDER_TYPE_DEFAULT = 0;
  PROVIDER_TYPE_FLEX_TARIFF_GROUP = 1;
  PROVIDER_TYPE_FLEX_TARIFF_ITEM = 2;
}

enum ConnectivityEnum {
  CONNECTIVITY_UNSPECIFIED = 0;
  CONNECTIVITY_ONLINE = 1;
  CONNECTIVITY_OFFLINE = 2;
}

enum FirmwareFilterEnum {
  UNSPECIFIED = 0;
  STATUS_AVAILABLE = 1;
}


// The phase wiring of the Connector with respect to the grid phases.
// L1, L2, and L3, denote the grid phases.
// The position of these symbols denotes the phases on the connector.
// xx denotes that the phase is not connected.
enum Wiring {
  // The wiring data was not specified.
  WIRING_UNSPECIFIED = 0;

  // The wiring data is unknown.
  WIRING_UNKNOWN = 1;

  // All grid phases are connected to the connector in the same order.
  WIRING_L1L2L3 = 2;

  // The grid phases are connected to the connector and shifted by 120 deg.
  WIRING_L3L1L2 = 3;

  // The grid phases are connected to the connector and shifted by 240 deg.
  WIRING_L2L3L1 = 4;

  // Only the L1 grid phase is connected to the L1 connector phase.
  // The L2 and L3 are not connected.
  WIRING_L1xxxx = 5;

  // Only the L2 grid phase is connected to the L1 connector phase.
  // The L1 and L3 are not connected.
  WIRING_L2xxxx = 6;

  // Only the L3 grid phase is connected to the L1 connector phase.
  // The L2 and L3 are not connected.
  WIRING_L3xxxx = 7;
}

// The network entity, it includes emsp and cpo providers. The id for the
// same network should be same across the system.
message Network {
  // the id of the network
  int32 id = 1;
  // the name of the network, i.e. Qwello Sverige
  string name = 2 [ (validate.rules).string.min_len = 1 ];
  // the source of the network
  NetworkRoamingSourceEnum source = 3
  [ (validate.rules).enum = {not_in : [ 0 ]} ];
}

message DeploymentGroup {
  // name of the deployment group
  string name = 1;
  // Configuration patch applied before the patch of the country and the
  // individual patch configuration
  string config_patch = 2;
}

// The cpo provider
message Provider {
  // the id of the provider
  int32 id = 1;
  // the party_id, i.e. DEQWC
  string party_id = 2 [ (validate.rules).string.len = 5 ];
  // optional sub_organization, ie. DEQWC Munich
  string sub_organization = 3;
  // The name of the provider
  string name = 4 [ (validate.rules).string.min_len = 1 ];
  // for child providers
  int32 parent_id = 5;
  // whether this is a flex or fixed cpo
  ProviderTypeEnum type = 6;
  // the network of the provider
  int32 network_id = 7 [ (validate.rules).int32.gt = 0 ];
}

message Country {
  int32 id = 1;
  string name = 2 [ (validate.rules).string.min_len = 1 ];
  string country_code = 3 [ (validate.rules).string.len = 2 ];
  string alpha_3_country_code = 4 [ (validate.rules).string.len = 3 ];
  // Configuration patch applied before the patch of the city and the
  // patch for the deployment group
  string config_patch = 5;
}
// Regions are the part of Country
message Region {
  int32 id = 1;
  // required country of the region
  int32 country_id = 2 [ (validate.rules).int32.gt = 0 ];
  // required name of the region
  string name = 3 [ (validate.rules).string.min_len = 1 ];
}

// City is the part of region
message City {
  int32 id = 1;
  // required name of the city
  string name = 2 [ (validate.rules).string.min_len = 1 ];
  // required region id
  int32 region_id = 3 [ (validate.rules).int32.gt = 0 ];
  // the optional center of the city.
  message Center {
    float latitude = 1 [ (validate.rules).float = {not_in : [ 0 ]} ];
    float longitude = 2 [ (validate.rules).float = {not_in : [ 0 ]} ];
  }
  Center center = 4;
  // timezone of the city
  string time_zone = 5 [ (validate.rules).string.min_len = 1 ];
  // region where the city is
  Region region = 6;
  // country where the the city is
  Country country = 7;
  // Configuration patch applied before individual pole configuration
  string config_patch = 8;
  // Some backend-configuration for the city: json object
  string features_configuration = 9;
  // when the city was created
  google.protobuf.Timestamp created = 10;
}

// District is a part of the city
message District {
  int32 id = 1;
  // required name of the district
  string name = 2;
  // required city_id
  int32 city_id = 3;
}
// The address of the Location
message Address {
  string city = 1 [ (validate.rules).string.min_len = 1 ];

  string zipcode = 2 [ (validate.rules).string.min_len = 1 ];
  string street = 3 [ (validate.rules).string.min_len = 1 ];
  string house_num = 4;
  // alpha-3 country code
  string country = 5 [ (validate.rules).string = {max_len : 3, min_len : 3} ];
  // optional location_name
  optional string location_name = 6;
}

message Location {
  // the uuid of the location, if not set, is created automatically
  string uuid = 1 [ (validate.rules).string.max_len = 36 ];
  // the base, used for pool_id and for the evse creation on this location, if
  // not provided, will be automatically created from the cpo party_id.
  string evse_base = 2 [ (validate.rules).string.max_len = 48 ];
  // the evse_pool id, used by Hubject for grouping of the stations. If not
  // provided, build from evse_base
  string evse_pool_id = 3 [ (validate.rules).string.max_len = 36 ];
  // the name of the Location, by default the street + house_num from address
  string name = 4;
  // location type if not_set, unknown will be used in the database
  LocationTypeEnum location_type = 5;
  // The address of the location
  Address address = 6;
  // the coordinates of the Location
  float latitude = 7 [ (validate.rules).float = {not_in : [ 0 ]} ];
  float longitude = 8 [ (validate.rules).float = {not_in : [ 0 ]} ];
  // the timezone of the Location, if not present on the creation, will be taken
  // from city_id
  string time_zone = 9;
  // if the Location is Qwello or Roaming
  LocationSourceEnum source = 10;
  // city id, used for statistics
  int32 city_id = 11 [ (validate.rules).int32.gt = 0 ];
  // the district, used for statistics
  int32 district_id = 12;
  // the cpo provider of the location
  Provider provider = 13;
  // if the location in draft state or not
  ReadinessEnum readiness = 14;
  // if the location is real or simulated
  SimulatedEnum simulated = 15;
  // if the location is public or not
  AccessibilityEnum accessibility = 16;
  // the evses
  repeated EVSE evses = 17;
  // the last update of the Location
  google.protobuf.Timestamp last_updated = 18;
  // when the location was created
  google.protobuf.Timestamp created = 19;
  // due to the problems with structure at backend, some locations should not be
  // synced into the backend. Once all the offending locations are retired, this
  // could be deprecated
  SyncToBackend sync_to_backend = 20;
  // when the pole became live
  google.protobuf.Timestamp live_at = 21;
  // The software bundle of this Location.
  string deployment_group = 22;
  // The pole model
  string pole_model = 23;
  google.protobuf.Timestamp last_paired_at = 24;
  // optional alias of the location
  string alias = 25;
  // The identifier of the gird connection.
  // The value should always be a non-empty string. An empty string means that the
  // location is not part of any grid connection, which is not allowed
  // (except in the transition period - while this new field is being rolled out).
  string grid_connection_uuid = 26;
  City city = 27;
  google.protobuf.Timestamp deleted_at = 28;
  // Whether this pole is considered online or offline,
  // determined by whether it has been communicating with the backend recently.
  ConnectivityEnum connectivity = 29;
  // The timestamp of the last heartbeat sent to the backend.
  google.protobuf.Timestamp last_seen_at = 30;
  // The serial number of the pole that is connected to the Location
  string pole_serial = 31;
  // The previous Greenflux ID of the pole. Optional. Present only for poles which have been
  // migrated from the Greenflux backend but not yet fitted with new stickers.
  string greenflux_id = 32;
}

enum ReservationStatus {
  RESERVATION_STATUS_UNSPECIFIED = 0;
  // Accepted
  RESERVATION_STATUS_ACCEPTED = 1;
  // Rejected
  RESERVATION_STATUS_REJECTED = 2;
  // Canceled e.g. a reservation is canceled
  RESERVATION_STATUS_CANCELED = 3;
}

message EVSE {
  string uuid = 1 [ (validate.rules).string.max_len = 36 ];
  string evse_id = 2 [ (validate.rules).string.max_len = 48 ];
  // the name of the EVSE, usually the name of Location + - 1,
  // i.e. Barer Str. - 1
  string name = 3;
  // The status of the station. The parking sensor status is the internal and
  // not exposed for now.
  EVSEStatusEnum status = 4;
  // This is deprecated. Only readiness fo the Location means anything
  // TODO: delete and mark as reserved once it is not used anywhere.
  // For compatibility reasons readiness=READY will be returned
  ReadinessEnum readiness = 5 [ deprecated = true ];
  // the coordinates of the EVSE
  float latitude = 6;
  float longitude = 7;
  repeated Connector connectors = 8;
  // the last update of the EVSE
  google.protobuf.Timestamp last_updated = 9;
  // when the EVSE was created
  google.protobuf.Timestamp created = 10;
  // If connected to the Pole
  EVSEPairedEnum paired = 11;
  // The optional connected Pole, returned only for the FULL View
  Pole pole = 12;
  // the list of features
  repeated FeatureEnum features = 13;
  // the expected value of the maintenance mode of this pole
  MaintenanceModeEnum maintenance_mode = 14;
  // Information about the current maintenance mode. Present when maintenance_mode is `ON`, absent
  // otherwise.
  MaintenanceModeDetails maintenance_mode_details = 22;
  // optional public key
  string public_key = 15;
  // list of the last reasons the EVSE was offline
  repeated string out_of_order_reason = 16;
  // If stations is paired indicates the pairing time. None otherwise
  google.protobuf.Timestamp last_paired_at = 17;
  // DEPRECATED due to incorrect enum
  ReservationStatus reservation_status = 18 [ deprecated = true ];
  // optional alias of the evse
  string alias = 19;
  // Defined if the pole has an ongoing reservation
  EVSEReservationStatus reservation_status_v2 = 20;
  google.protobuf.Timestamp deleted_at = 21;
  // The timestamp of the last change of state sent to the backend.
  google.protobuf.Timestamp pole_state_update_timestamp = 23;
}

message Connector {
  string uuid = 1 [ (validate.rules).string.max_len = 36 ];
  // The socket type
  ConnectorTypeEnum connector_standard = 2;
  // If socket has the integrated cable
  ConnectorFormatEnum connector_format = 3;
  // If AC or DC
  PowerTypeEnum power_type = 4;
  // Voltage in volts
  int32 voltage = 5;
  // Amperage in Amper
  int32 amperage = 6;
  // the last update of the connector
  google.protobuf.Timestamp last_updated = 7;
  // when the connector was created
  google.protobuf.Timestamp created = 8;
  // the wiring of the connector
  Wiring wiring = 9;
}

message Pole {
  // The serial number of the Pole
  string serial = 1;
  // The serial number of the tarragon
  string tarragon_serial = 2;
  // the mac address of the tarragon
  string mac_address = 3;
  // the meter public key
  string public_key = 4;
  // DEPRECATED optional payment terminal configuration id. (id of the entry in db)
  int32 payment_terminal_configuration_id = 5;
  string model = 6;
}

message PoleConfiguration {
  // DEPRECATED, use evse_base for communication instead
  string evse_id = 1;
  // the serial number of the metal part
  string pole_serial_number = 2;
  // the model of the pole
  string model = 3;
  // json string with settings
  string configuration = 4;
  // mac address
  string mac_address = 5;
  // time zone i.e. Europe/Berlin
  string timezone = 6;
  message ReverseSshConfig {
    // the address for the reverse ssh, currently only 18.198.128.94
    string address = 1;
    // the reverse ssh port from 5000 to 7000 unique
    int32 port = 2;
  }
  ReverseSshConfig reverse_ssh = 7;
  float offline_threshold = 8;
  // The id of the payment terminal that we received from the payment provider
  string payment_terminal_id = 9;
  // the serial number of the feig terminal.
  string feig_serial = 10;
  // DEPRECATED the expected value of the maintenance mode of this pole
  MaintenanceModeEnum maintenance_mode = 11;
  // Values the pole measured
  PoleMeasurements measurements = 12;
  // The software specification.
  string deployment_group = 13;
  // DEPRECATED Additional maintenance mode details such as type and cause.
  MaintenanceModeDetails maintenance_mode_details = 14;
  // The location identifier. If the pole is not paired, it will be empty.
  string evse_base = 15;
  repeated EVSEMaintenanceMode evse_ids_maintenance_mode_details = 16;
  string display_serial = 17;
}

// All about maintenance mode for one evse_id
message EVSEMaintenanceMode {
  string evse_id = 1;
  MaintenanceModeEnum maintenance_mode = 2;
  MaintenanceModeDetails maintenance_mode_details = 3;
}

// Top left and bottom right coordinates
message RectangleCoordinates {
  float nw_lat = 1;
  float nw_lon = 2;
  float se_lat = 3;
  float se_lon = 4;
}

// Represents a company from which Qwello buys electricity
message ElectricityProvider {
  int32 id = 1;
  string name = 2;
}

// like scientific format, but with integer as a mantissa
// 0,0183 euro is [183, -4]
message CostFormat {
  // https: // en.wikipedia.org/wiki/Significand
  int32 significand = 1;
  int32 power = 2;
}

// Represents the price for electricity that we pay to the electricity provider
message ElectricityTariff {
  int32 id = 1;
  // The cost of electricity that we estimate based on the previous payments to
  // this provider
  CostFormat estimated_cost_per_kwh = 2;
  // The real cost of electricity that we pay this provider. This is usually
  // known only after they measure the usage
  CostFormat final_cost_per_kwh = 3;
  // The 3-letter currency code
  string currency = 4;
  // The company we buy electricity from
  ElectricityProvider provider = 5;
}

// An electricity cost is an Electro Tariff for a specific place and time range
message ElectricityCost {
  // The id of the cost
  int32 id = 1;

  // The time range when this tariff is effective must not overlap with other
  // tariffs for the same area (see below)
  google.type.Date start_date = 2;
  google.type.Date end_date = 3;

  // The area for which this cost is valid: One is set: either country,
  // region, city, district or location group.
  int32 country_id = 4;
  int32 region_id = 5;
  int32 city_id = 6;
  int32 district_id = 7;
  string locations_group_uuid = 8;



  // The electricity tariff
  ElectricityTariff tariff = 9;
}

message ListElectricityProvidersRequest {}
message ListElectricityProvidersResponse {
  repeated ElectricityProvider providers = 1;
}

message RenameElectricityProviderRequest {
  int32 id = 1;
  string name = 2;
}
message RenameElectricityProviderResponse { ElectricityProvider provider = 1; }

message ListElectricityTariffsRequest {}
message ListElectricityTariffsResponse { repeated ElectricityCost tariffs = 1; }

message UpdateElectricityTariffRequest {
  // The id of the ElectricityTariff
  int32 tariff_id = 1;
  // The cost of electricity that we estimate based on the previous payments to
  // this provider. Empty / omitted values do not change the current value.
  CostFormat estimated_cost_per_kwh = 2;
  // The real cost of electricity that we pay this provider. This is usually
  // known only after they measure the usage.
  // Empty / omitted values do not change the current value.
  CostFormat final_cost_per_kwh = 3;
  // The field mask of the fields that should be updated.
  google.protobuf.FieldMask update_mask = 4;
  // The email of the user that requested the update
  string user_email = 5;
  // The electricity provider for this area
  ElectricityProvider electricity_provider = 6;
}
message UpdateElectricityTariffResponse { ElectricityTariff tariff = 1; }

message CreateNetworkRequest { Network network = 1; }

message GetNetworkRequest {
  // the id of the network
  int32 id = 1 [ (validate.rules).int32.gt = 0 ];
}

message ListNetworksRequest {}
message ListNetworksResponse { repeated Network networks = 1; }

message CreateProviderRequest {
  Provider provider = 1;
}
message CreateProviderResponse {
  Provider provider = 1;
}

message ListProvidersRequest {
  // id of the network
  int32 network_id = 1 [ (validate.rules).int32.gt = 0 ];
}
message ListProvidersResponse { repeated Provider providers = 1; }

message ListCountriesRequest {
  int32 network_id = 1;
}
message ListCountriesResponse { repeated Country countries = 1; }

message GetCountryRequest {
  int32 country_id = 1 [ (validate.rules).int32.gt = 0 ];
}
message GetCountryResponse { Country country = 1; }

message CreateRegionRequest { Region region = 1; }
message ListRegionsRequest {
  int32 country_id = 1 [ (validate.rules).int32.gt = 0 ];
  int32 provider_id = 2;
}
message ListRegionsResponse { repeated Region regions = 1; }

message UpdateRegionRequest {
  Region region = 1;
  // The field mask of the fields that should be updated.
  // Currently only name can be patched.
  google.protobuf.FieldMask update_mask = 2;
}

message CreateCityRequest { City city = 1; }

message GetCityRequest { int32 city_id = 1 [ (validate.rules).int32.gt = 0 ]; }

message ListCitiesRequest {
  int32 region_id = 1 [ (validate.rules).int32.gt = 0 ];
}
message ListCitiesResponse { repeated City cities = 1; }

message UpdateCityRequest {
  City city = 1;
  // The field mask of the fields that should be updated.
  // Currently only name can be patched.
  google.protobuf.FieldMask update_mask = 2;
}

message SearchCitiesRequest {
  // deprecated
  string filter = 1;
  // Optional
  int32 region_id = 2;
  // Optional
  int32 country_id = 3;
  // Optional
  google.protobuf.Timestamp created_after = 4;
  // Optional
  int32 provider_id = 5;
}
message SearchCitiesResponse { repeated City cities = 1; }

message SearchDeploymentGroupsRequest {
  // optional filter name="xxx", if not present all deployment groups are
  // returned
  string filter = 1 [ (validate.rules).string = {
    ignore_empty : true,
    pattern : "name=[A-Za-z0-9_]+$"
  } ];
}

message SearchDeploymentGroupsResponse {
  repeated DeploymentGroup deployment_groups = 1;
}

message ListDistrictsRequest {
  int32 city_id = 1 [ (validate.rules).int32.gt = 0 ];
}
message ListDistrictsResponse { repeated District districts = 1; }

message ListLocationsRequest {
  int32 provider_id = 1 [ (validate.rules).int32.gt = 0 ];
}

message CreateQwelloLocationRequest {
  int32 provider_id = 1 [ (validate.rules).int32.gt = 0 ];
  // the required fields have to be set, will create the default configuration,
  // in DRAFT state.
  Location location = 2;
  // the amount evses to be created
  int32 evse_count = 3;
}

message CreateLocationsGroupRequest { LocationsGroup group = 1; }
message CreateLocationsGroupResponse { LocationsGroup group = 1; }

// Represents the update location request. Only load_limit could be updated
message UpdateLocationsGroupRequest {
  // Contains changed fields
  LocationsGroup group = 1;
  // contains the updated fields
  google.protobuf.FieldMask update_mask = 2;
}

message DeleteLocationsGroupRequest {
  // The uuid of the locations group to delete
  string uuid = 1;
  // The email address of the user that requested the deletion
  string user_email = 2;
}

message DeleteLocationsGroupResponse {}

message UpdateLocationsGroupResponse { LocationsGroup group = 1; }

message ListLocationsResponse { repeated Location locations = 1; }

message AdjustEVSECountRequest {
  string location_uuid = 1 [ (validate.rules).string.min_len = 1 ];
  int32 new_count = 2;
}
message AdjustEVSECountResponse { Location location = 1; }


message AdjustLocationsCountRequest {
