message GetEVSEMaintenanceResponse {
  // The evse_id of the charge point
  string evse_id = 1;
  // The status of the maintenance mode -- NB this might not be effective yet!
  MaintenanceModeEnum mode = 2;
  // If maintenance mode is active: The reason given when that was setting
  string reason = 3;
  // The time at which the last maintenance mode change was requested.
  google.protobuf.Timestamp last_changed_at = 4;
  // Additional details such as type and cause.
  MaintenanceModeDetails details = 5;
  // The first time when the pole booted with maintenance mode being ON for this
  // setting.
  google.protobuf.Timestamp pole_changed_into_maintenance_at = 6;
}

enum MaintenanceModeTypeEnum {
  MAINTENANCE_MODE_TYPE_UNSPECIFIED = 0;
  // Unplanned downtime, e.g. due to hardware issues with the pole.
  MAINTENANCE_MODE_TYPE_BROKEN = 1;
  // Planned downtime, due to third party access restrictions.
  // e.g. A festival or construction side is blocking access to our pole.
  // For this type, please also specify the cause.
  MAINTENANCE_MODE_TYPE_PLANNED = 2;
  // The EVSE is being commissioned (not yet available to the public).
  MAINTENANCE_MODE_TYPE_COMING_SOON = 3;
}

enum MaintenanceModeCauseEnum {
  MAINTENANCE_MODE_CAUSE_UNSPECIFIED = 0;
  // The access to the pole is temporarily blocked due to a construction
  // site in the area.
  MAINTENANCE_MODE_CAUSE_CONSTRUCTION_SITE = 1;
  // The access to the pole is temporarily blocked due to a festival or
  // other type of festivity happening in the area.
  MAINTENANCE_MODE_CAUSE_FESTIVAL = 2;
}

enum MaintenanceModePoleResetSettingEnum {
  // That is the default value and means MAINTENANCE_MODE_RESET_AUTOMATIC.
  MAINTENANCE_MODE_RESET_UNSPECIFIED = 0;
  // The pole should be reset automatically and no explicit reset is required.
  MAINTENANCE_MODE_RESET_AUTOMATIC = 1;
  // The pole should not be reset automatically: the client is managing
  // resetting the pole itself by sending a reset QCPP command.
  // This allows the client to react to missing ACKs / failing commands.
  MAINTENANCE_MODE_RESET_NO = 2;
}

message MaintenanceModeDetails {
  // The type of maintenance mode, e.g. for distinguishing between unplanned
  // errors and planned access restrictions. The type also dictates which screen
  // will be displayed on the pole e.g. the screwdrivers for type "BROKEN".
  MaintenanceModeTypeEnum type = 1;
  // This is indented to be use in the case of the "PLANNED" type. It describes
  // the class of reasons for our pole to not be open to the public right now.
  // e.g. access is restricted due to a construction site in the area.
  MaintenanceModeCauseEnum cause = 2;
  // Similar to the cause, but in free-form text since this includes the
  // translations to other languages and any required adaptations to the cause.
  // This is the message that will be displayed to the screen. This can be left
  // empty unless the cause is specified (i.e. type is PLANNED).
  string text_to_display = 3;
  // The reason as given when setting the EVSE maintenance mode. This field is
  // ignored when seting the EVSE maintenance mode via the API.
  string reason = 4;
}

