  // The status of the maintenance mode to activate or deactivate on the
  // given EVSE/station.
  MaintenanceModeEnum mode = 2;
  // The reason for setting that EVSE/station to maintenance (required when
  // setting).
  string reason = 3;
  // Additional details. Mandatory when the mode is ON.
  // Please only set this field when the mode is ON.
  MaintenanceModeDetails details = 4;
  // Optional field for adding to maintenance at a different start date.
  // This can only be used with mode ON.
  google.protobuf.Timestamp requested_start = 5;
  // Optional field to control if the pole should be reset implicitly or not
  // at all and eventually with retries. Default is to reset.
  MaintenanceModePoleResetSettingEnum reset_mode = 6;
}

