    AUTHORIZATION_PARADIGM_INDIVIDUAL = 1;
    AUTHORIZATION_PARADIGM_GROUP = 2;
  }
  AuthorizationParadigm autorization = 5;
  enum ParkingSensor {
    PARKING_SENSOR_UNSPECIFIED = 0;
    PARKING_SENSOR_PRESENT = 1;
    PARKING_SENSOR_NONE = 2;
  }
  ParkingSensor parking_sensor = 6;
}

