message SetLocationGroupAsRegisteredResponse {}

message AddToMaintenanceModeHistoryResponse {}

// Identity of the pole is used to identify the pole on
// backend side. We use two Identities now.
//   1. openSSL certificate, that is used for gRPC communication
//   2. public ssh key that is used for software update and reverse-ssh.
message PoleIdentity {
  // Serial of the station
  string pole_serial = 1;
  // Openssl certificate used to authenticate the pole
  // in Eugene
  string certificate = 2;
  // Ssh public key, used for reverse-ssh connection
  string ssh_key = 3;
  // Date and time of issue
  google.protobuf.Timestamp issued_at = 4;
}

message AddPoleIdentityRequest {
  // Public Identities of the pole
  PoleIdentity identity = 2;
}

message AddPoleIdentityResponse {}

message GetPoleIdentityRequest {
  // the serial number of the Pole
  string pole_serial = 1;
}

message GetPoleIdentityResponse {
  // Public Identity of the pole
  PoleIdentity identity = 1;
}

message AddAliasByPoleSerialRequest {
  // Pole alias either CPXXXX{connector_id} or EBXXXX fir evse_base
  string alias = 1;
  // Pole serial number
  string pole_serial = 2;
}

message AddAliasByPoleSerialResponse { Location location = 1; }

message GetLocationByAliasRequest {
  // Pole alias either CPXXXX{connector_id} or EBXXXX fir evse_base
  string alias = 1;
}

message GetLocationByAliasResponse { Location location = 1; }

message CreatePoleRequest {
  string pole_serial = 1;
  string pole_model = 2;
  optional string pole_notes = 3;
}

message CreatePoleResponse {}

message DeletePoleRequest {
  string pole_serial = 1;
}

message DeletePoleResponse {}

// DEPRECATED will not do anything anymore
message RemoveLocationGroupRequest {
  // Required uuid of the locations group.
  string locations_group_uuid = 1;
}

message RemoveLocationGroupResponse {}

message CreateGridConnectionRequest {
  // The uuid of the locations group.
  string locations_group_uuid = 1;
  // The maximum load/amperage supported by the grid connection.
  // Going above this limit can trip the fuse.
  int32 load_limit = 2;
  // A list of location uuids that are connected to this grid connection.
  repeated string locations_uuids = 3;
  // Optional Service Delivery Point id
  string sdp = 4;
  // Private or public grid connection
  GridConnectionOwnerType owner_type = 5;
  // Optional: Name of the owner.
  // This field might make sense only for the private owner type.
  // This is not enforced in code.
  string owner_name = 6;
}

message GetGridConnectionRequest {
  string uuid = 1;
}

message UpdateGridConnectionRequest {
  string uuid = 1;
  GridConnection grid_connection = 2;
  google.protobuf.FieldMask field_mask = 3;
}

message GridConnection {
  // The uuid of the grid connection.
  string uuid = 1;
  // The uuid of the locations group.
  string locations_group_uuid = 2;
  // The maximum load/amperage supported by the grid connection.
  int32 load_limit = 3 [ (validate.rules).int32.gt = 0 ];
  // A list of location uuids that are connected to this grid connection.
  repeated string locations_uuids = 4;
  // An external id given to us by the grid provider.
  string grid_connection_id = 5 [deprecated = true];
  // Service delivery point: An external id given to us by the grid provider.
  string sdp = 6;
  // Private or public grid connection
  GridConnectionOwnerType owner_type = 7;
  // Optional: Name of the owner.
  // This field might make sense only for the private owner type.
  // This is not enforced in code.
  string owner_name = 8;
}

message RewireEvseRequest {
  // The id of the EVSE.
  string evse_id = 1;
  // The new wiring of all connectors belonging to the EVSE.
  Wiring new_wiring = 2;
}

message RewireEvseResponse {}

message MergeCitiesRequest {
  // The ids of the cities to be merged into "into"
  repeated int32 merged = 1;
  // The city id to replace those in "merged"
  int32 into = 2;
}

message MergeCitiesResponse {}

message GetGridConnectionBySDPRequest {
  // Service delivery point id
  string sdp = 1;
}

message GetGridConnectionBySDPResponse {
  GridConnection grid_connection = 1;
}

message GetGridConnectionByEVSERequest {
