  GRID_CONNECTION_EVENT_KIND_ENUM_UNSPECIFIED = 0;
  GRID_CONNECTION_EVENT_KIND_ENUM_CURTAIL = 1;
  GRID_CONNECTION_EVENT_KIND_ENUM_RESTORE = 2;
}

enum GridConnectionOwnerType {
