service StationsService {
  // creates network
  rpc CreateNetwork(CreateNetworkRequest) returns (Network) {
    option (google.api.http) = {
      post : "/stations-service/networks",
      body : "*"
    };
  }
  // returns network by id
  rpc GetNetwork(GetNetworkRequest) returns (Network) {
    option (google.api.http) = {
      get : "/stations-service/networks/{id}",
    };
  }
  // get all networks, only for admins
  rpc ListNetworks(ListNetworksRequest) returns (ListNetworksResponse) {
    option (google.api.http) = {
      get : "/stations-service/networks",
    };
  }
  // Search deployment groups
  rpc SearchDeploymentGroups(SearchDeploymentGroupsRequest)
          returns (SearchDeploymentGroupsResponse) {
    option (google.api.http) = {
      get : "/stations-service/deployment_groups"
    };
  }

  // Create a new CPO provider
  rpc CreateProvider(CreateProviderRequest) returns (CreateProviderResponse) {
    option (google.api.http) = {
      post : "/stations-service/providers",
      body : "*"
    };
  }

  // returns cpo providers for the given network
  rpc ListProviders(ListProvidersRequest) returns (ListProvidersResponse) {
    option (google.api.http) = {
      get : "/stations-service/networks/{network_id}/providers",
    };
  }

  rpc ListCountries(ListCountriesRequest) returns (ListCountriesResponse) {
    option (google.api.http) = {
      get : "/stations-service/countries",
    };
  }

  rpc GetCountry(GetCountryRequest) returns (GetCountryResponse) {
    option (google.api.http) = {
      get : "/stations-service/countries/{country_id}",
    };
  }

  // Creates a new region
  rpc CreateRegion(CreateRegionRequest) returns (Region) {
    option (google.api.http) = {
      post : "/stations-service/regions"
      body : "*"
    };
  }
  rpc ListRegions(ListRegionsRequest) returns (ListRegionsResponse) {
    option (google.api.http) = {
      get : "/stations-service/countries/{country_id}/regions",
    };
  }

  // Update region
  rpc UpdateRegion(UpdateRegionRequest) returns (Region) {
    option (google.api.http) = {
      patch : "/stations-service/regions/{region.id}"
      body : "*"
    };
  }

  // Creates a new city
  rpc CreateCity(CreateCityRequest) returns (City) {
    option (google.api.http) = {
      post : "/stations-service/cities"
      body : "*"
    };
  }

  // Update city
  rpc UpdateCity(UpdateCityRequest) returns (City) {
    option (google.api.http) = {
      patch : "/stations-service/cities/{city.id}"
      body : "*"
    };
  }

  // Get city by id
  rpc GetCity(GetCityRequest) returns (City) {
    option (google.api.http) = {
      get : "/stations-service/cities/{city_id}",
    };
  }

  // List cities in the region
  rpc ListCities(ListCitiesRequest) returns (ListCitiesResponse) {
    option (google.api.http) = {
      get : "/stations-service/regions/{region_id}/cities",
    };
  }
  // Can return all the cities, cities in the country, cities in the region.
  // The query parameter filer has to be provided in the form
  // filter=country_id=n or filter=region_id=n. If none is provided, all the
  // cities are returned.
  rpc SearchCities(SearchCitiesRequest) returns (SearchCitiesResponse) {
    option (google.api.http) = {
      get : "/stations-service/cities",
    };
  }

  // List districts in the city
  rpc ListDistricts(ListDistrictsRequest) returns (ListDistrictsResponse) {
    option (google.api.http) = {
      get : "/stations-service/cities/{city_id}/districts",
    };
  }
  // Deprecated, please use CreateQwelloLocationsGroup
  rpc CreateQwelloLocation(CreateQwelloLocationRequest) returns (Location) {}
  // List locations for the provider. Returns all the stations for that
  // provider For better querying see SearchLocations
  rpc ListLocations(ListLocationsRequest) returns (ListLocationsResponse) {
    option (google.api.http) = {
      get : "/stations-service/providers/{provider_id}/locations"
    };
  }
  // Deprecated

  rpc AdjustLocationsCount(AdjustLocationsCountRequest)
          returns (AdjustLocationsCountResponse) {
    option (google.api.http) = {
      patch : "/stations-service/locations_group/{group_uuid}/count",
      body : "*"
    };
  }

  rpc AdjustEVSECount(AdjustEVSECountRequest)
          returns (AdjustEVSECountResponse) {}
  // Get location by uuid
  rpc GetLocation(GetLocationRequest) returns (Location) {
    option (google.api.http) = {
      get : "/stations-service/locations/{location_uuid}"
    };
  }

  // Update the location, the fields possible to update can change depending
  // on the readiness state. Should include the update_mask. Will not update
  // the underlying evses. The fields, that can be updated: name,
  // location_type, all fields in address, latitude, longitude, time_zone,
  // city_id, district_id, readiness, simulated, accessibility. Can not change
  // readiness from ready to draft. Can not change accessibility from Public
  // to Internal.
  rpc UpdateLocation(UpdateLocationRequest) returns (Location) {
    option (google.api.http) = {
      patch : "/stations-service/locations/{location.uuid}",
      body : "*"
    };
  }
  // Search Locations by various parameters
  rpc SearchLocations(SearchLocationsRequest)
          returns (SearchLocationsResponse) {
    option (google.api.http) = {
      get : "/stations-service/locations"
    };
  }
  // Updates the evse by field mask, the possible fields are name, readiness,
  // latitude, longitude.
  rpc UpdateEVSE(UpdateEVSERequest) returns (EVSE) {
    option (google.api.http) = {
      patch : "/stations-service/locations/{location_uuid}/evses/"
              "{evse.uuid}",
      body : "*"
    };
  }
  // Looks in the database for the pole by the mac address.
  rpc GetPoleConfiguration(GetPoleConfigurationRequest)
          returns (GetPoleConfigurationResponse) {}

  // Will return list of the configurations based on the filter
  rpc SearchPoleConfiguration(SearchPoleConfigurationRequest)
          returns (SearchPoleConfigurationResponse) {
    option (google.api.http) = {
      get : "/stations-service/pole_configurations"
    };
  }

  // Allows to update pole configuration by the serial number of the pole. Only
  // json configuration of the pole could be changes for now.
  rpc UpdatePoleConfiguration(UpdatePoleConfigurationRequest)
          returns (UpdatePoleConfigurationResponse) {
    option (google.api.http) = {
      patch : "/stations-service/pole_configurations/{pole_serial_number}"
      body : "*"
    };
  }

  // Will return the pole by the serial number
  rpc GetPoleBySerial(GetPoleBySerialRequest)
          returns (GetPoleBySerialResponse) {
    option (google.api.http) = {
      get : "/stations-service/poles/{serial}"
    };
  }

  // Update various hardware info in the Pole / PoleConfiguration identifying
  // the pole by its serial number.
  rpc UpdatePoleHardwareInfo(UpdatePoleHardwareInfoRequest)
          returns (UpdatePoleHardwareInfoResponse) {
    option (google.api.http) = {
      patch : "/stations-service/poles/{pole_serial}/hardware"
      body : "*"
    };
  }



  rpc GetPoleHardwareInfo(GetPoleHardwareInfoRequest)
          returns (GetPoleHardwareInfoResponse) {
    option (google.api.http) = {
      get : "/stations-service/poles/{pole_serial}/hardware"
    };
  }

  // Returns, for all of the poles, the pole's serial, and the
  // corresponding EVSE's name and id. If the pole is not paired,
  // the name and id will be empty string.
  rpc GetPoleIdentifiers(GetPoleIdentifiersRequest)
          returns (GetPoleIdentifiersResponse) {
    option (google.api.http) = {
      get : "/stations-service/pole_identifiers"
    };
  };

  // Pair the Qwello Pole to the EVSE, and mark the EVSE's location as READY
  rpc PairPole(PairPoleRequest) returns (PairPoleResponse) {
    option (google.api.http) = {
      post : "/stations-service/evse/{evse_id}/pair",
      body : "*"
    };
  }

  rpc CreateLocationV2(CreateLocationV2Request)
          returns (CreateLocationV2Response) {
    option (google.api.http) = {
      post : "/stations-service/v2/locations_groups/{locations_group_uuid}/locations",
      body : "*"
    };
  }

  rpc DeleteLocationV2(DeleteLocationV2Request)
          returns (DeleteLocationV2Response) {
    option (google.api.http) = {
      delete : "/stations-service/v2/locations_groups/locations/{location_uuid}",
    };
  }

  rpc UpdateLocationV2(UpdateLocationV2Request)
          returns (UpdateLocationV2Response) {
    option (google.api.http) = {
      patch : "/stations-service/v2/locations_groups/locations/{location_uuid}",
      body : "*"
    };
  }

  // Unpair the Qwello Pole and the EVSE
  rpc UnpairPole(UnpairPoleRequest) returns (UnpairPoleResponse) {
    option (google.api.http) = {
      post : "/stations-service/evses/{evse_id}/unpair",
    };
  }

  // Reset payment terminal assignment for location
  rpc ResetPaymentTerminalAssignmentForLocation(ResetPaymentTerminalAssignmentForLocationRequest) returns (ResetPaymentTerminalAssignmentForLocationResponse) {
    option (google.api.http) = {
      delete : "/stations-service/locations/{location_uuid}/tid"
    };
  }
  // Simplified creation of Qwello LocationsGroups, only to create
  // LocationsGroups from scratch. Could not be used to create the specific
  // locations.
  rpc CreateQwelloLocationsGroup(CreateQwelloLocationsGroupRequest)
          returns (CreateQwelloLocationsGroupResponse) {
    option (google.api.http) = {
      post : "/stations-service/providers/{provider_id}/"
              "qwello_locations_groups",
      body : "*"
    };
  }

  rpc CreateLocationsGroupV2(CreateLocationsGroupV2Request)
          returns (CreateQwelloLocationsGroupResponse) {
    option (google.api.http) = {
      post : "/stations-service/v2/providers/{provider_id}/"
              "locations_groups",
      body : "*"
    };
  }
  // The normal creation, could be used for example for migration of data,
  // because it requires you to specify everything up to EVSE. Connectors will
  // be created still automatically
  rpc CreateLocationsGroup(CreateLocationsGroupRequest)
          returns (CreateLocationsGroupResponse) {
    option (google.api.http) = {
      post : "/stations-service/locations_groups",
      body : "*"
    };
  }

  rpc UpdateLocationsGroup(UpdateLocationsGroupRequest)
          returns (UpdateLocationsGroupResponse) {
    option (google.api.http) = {
      patch : "/stations-service/locations_groups/{group.uuid}",
      body : "*"
    };
  }

  rpc DeleteLocationsGroup(DeleteLocationsGroupRequest)
          returns (DeleteLocationsGroupResponse) {
    option (google.api.http) = {
      delete : "/stations-service/locations_groups/{uuid}"
    };
  }

  // The communication initiated by the Pole. Eugene will pass the message to
  // the stations service. The timeout used by Eugene is 30 seconds.
  // If response from the stations_service did not come in time, the Pole will
  // receive `DEADLINE_EXCEEDED` StatusCode. If the EVSE is not found, eugene
  // will return StatusCode `NOT_FOUND`.
  rpc SendQcppMessage(SendQcppMessageRequest)
          returns (SendQcppMessageResponse) {};
  // Returns the LocationsGroups by filter, if nothing to filter by, returns
  // everything.
  rpc SearchLocationsGroups(SearchLocationsGroupsRequest)
          returns (SearchLocationsGroupsResponse) {
    option (google.api.http) = {
      get : "/stations-service/locations_groups"
    };
  };
  // Receives command from the "front-end" applications and puts it into the
  // queue. Where Eugene can get it from. Then reads the db, waiting for the
  // QCPPCommandResponse. If the entry in db does not appear in time,
  // DEADLINE_EXCEEDED error is thrown.
  rpc SendQcppCommand(SendQcppCommandRequest)
          returns (SendQcppCommandResponse) {
    option (google.api.http) = {
      post : "/stations-service/evses/{command.evse_id}/command",
      body : "*"
    };
  }

  // Will create the payment terminal object in the database.
  // DEPRECATED
  rpc CreatePaymentTerminalConfiguration(
          CreatePaymentTerminalConfigurationRequest)
          returns (CreatePaymentTerminalConfigurationResponse) {
    option (google.api.http) = {
      post : "/stations-service/payment_terminal_configurations",
      body : "*"
    };
  };

  // Will return payment terminal configuration
  // DEPRECATED
  rpc GetPaymentTerminalConfiguration(GetPaymentTerminalConfigurationRequest)
          returns (GetPaymentTerminalConfigurationResponse) {
    option (google.api.http) = {
      get : "/stations-service/payment_terminal_configurations/{id}"
    };
  };

  // Can change the payment terminal. The only field could be changed
  // currently is locations_group_uuid.
  rpc UpdatePaymentTerminalConfiguration(
          UpdatePaymentTerminalConfigurationRequest)
          returns (UpdatePaymentTerminalConfigurationResponse) {
    option (google.api.http) = {
      patch : "/stations-service/payment_terminal_configurations",
      body : "*"
    };
  };

  // Will assign the payment terminal to the Pole, if the locations_group_uuid
  // will not match one between pole's evse, the alert will be sent to the
  // sns. IF the terminal is paired already InvalidArgument message will be
  // return.
  rpc PairPaymentTerminalConfiguration(PairPaymentTerminalConfigurationRequest)
          returns (PairPaymentTerminalConfigurationResponse) {
    option (google.api.http) = {
      post : "/stations-service/payment_terminal_configurations/pair",
      body : "*"
    };
  };

  // Will unpair the payment terminal from the Pole
  rpc UnpairPaymentTerminalConfiguration(
          UnpairPaymentTerminalConfigurationRequest)
          returns (UnpairPaymentTerminalConfigurationResponse) {
    option (google.api.http) = {
      post : "/stations-service/payment_terminal_configurations/unpair",
      body : "*"
    };
  };

  rpc RequestTIDForLocation(RequestTIDForLocationRequest)
          returns (RequestTIDForLocationResponse) {
    option (google.api.http) = {
      post : "/stations-service/locations/{location_uuid}/request_tid",
      body : "*"
    };
  };

  // Will return the electricity tariff for a particular locations group and
  // date. If the tariff does not exist, RpcError NOT_FOUND will be returned.
  rpc GetElectricityTariffForLocationsGroup(
          GetElectricityTariffForLocationsGroupRequest)
          returns (GetElectricityTariffForLocationsGroupResponse) {};

  // Will return the electricity tariffs that correspond to the ids provided.
  // The ordered of returned tariffs may not match the initial order of ids.
  rpc GetElectricityTariffsForIds(GetElectricityTariffsForIdsRequest)
          returns (GetElectricityTariffsForIdsResponse) {};

  rpc ListElectricityProviders(ListElectricityProvidersRequest)
          returns (ListElectricityProvidersResponse) {
    option (google.api.http) = {
      get : "/stations-service/electricity_providers"
    };
  };

  rpc RenameElectricityProvider(RenameElectricityProviderRequest)
          returns (RenameElectricityProviderResponse) {
    option (google.api.http) = {
      post : "/stations-service/electricity_providers/{id}/rename",
      body : "*"
    };
  };

  rpc ListElectricityTariffs(ListElectricityTariffsRequest)
          returns (ListElectricityTariffsResponse) {
    option (google.api.http) = {
      get : "/stations-service/electricity_tariff"
    };
  };

  rpc UpdateElectricityTariff(UpdateElectricityTariffRequest)
          returns (UpdateElectricityTariffResponse) {
    option (google.api.http) = {
      patch : "/stations-service/electricity_tariff/{tariff_id}",
      body : "*"
    };
  };

  // Read if the given EVSE is in Maintenance Mode and some details if it is.
  rpc GetEVSEMaintenance(GetEVSEMaintenanceRequest)
          returns (GetEVSEMaintenanceResponse) {
    option (google.api.http) = {
      get : "/stations-service/evses/{evse_id}/maintenance"
    };
  };

  // Set the given EVSE into or out of Maintenance Mode depending on the
  // provided argument. Note that typically the "whole pole" assigned to this
  // EVSE is going to be configured as in/out of maintenance. Note also that
  // the pole might not follow this direction immediately (e.g. since it is
  // still busy with charging or communication is troublesome)
  rpc SetEVSEMaintenance(SetEVSEMaintenanceRequest)
          returns (SetEVSEMaintenanceResponse) {
    option (google.api.http) = {
      post : "/stations-service/evses/{evse_id}/maintenance",
      body : "*"
    };
  };

  // Get all cards that are whitelisted to still be allowed to authorize at a
  // pole that is in Maintenance Mode.
  rpc GetWhitelistedCardsForMaintenanceMode(
          GetWhitelistedCardsForMaintenanceModeRequest)
          returns (GetWhitelistedCardsForMaintenanceModeResponse) {
    option (google.api.http) = {
      get : "/stations-service/cards/whitelisted_for_maintenance_mode"
    };
  };

  // Add the given card to the list of whitelisted cards that can still
  // be used to authorize at a pole that is in Maintenance Mode.
  rpc WhitelistCardForMaintenanceMode(WhitelistCardForMaintenanceModeRequest)
          returns (WhitelistCardForMaintenanceModeResponse) {
    option (google.api.http) = {
      post : "/stations-service/cards/whitelisted_for_maintenance_mode",
      body : "*"
    };
  };

  // Remove the given card from the list of whitelisted cards that can still
  // be used to authorize at a pole that is in Maintenance Mode.
  rpc RemoveWhitelistedCardForMaintenanceMode(
          RemoveWhitelistedCardForMaintenanceModeRequest)
          returns (RemoveWhitelistedCardForMaintenanceModeResponse) {
    option (google.api.http) = {
